"""The migrations in alembic/versions/ build exactly the schema app/db/models.py describes."""

import pytest
from alembic import command
from alembic.config import Config


@pytest.mark.usefixtures("db_engine")  # it has already run every migration on the test DB
def test_every_model_change_has_a_migration(alembic_config: Config) -> None:
    # Autogenerate compares the models with the migrated test database. If someone edits
    # models.py without generating a migration, this raises AutoGenerateDiffsDetected and
    # names the difference (e.g. "add_column trades.foo").
    command.check(alembic_config)
